import { Fragment, useCallback } from 'react'
import { useSelector, useDispatch } from 'react-redux'

import './StageParticipantsList.scss'
import { TYPE_DOUBLES, TYPE_SINGLES } from '../../../utils/constants'
import { selectChosenPlayerInList, selectPlayersList, selectProcessedStage, selectTournament } from '../../../redux/selectors'
import { setChosenPlayerInList, setShowForbiddenMessage } from '../../../redux/stageService/stageSlice'
import { nodeIsPlaying } from '../../../utils/functions2'

function StageParticipantsList({ isFormTab }) {
	const dispatch = useDispatch()
	const playersList = useSelector(selectPlayersList)
	const chosenPlayerInList = useSelector(selectChosenPlayerInList)
	const stageState = useSelector(selectProcessedStage)
	const { type } = useSelector(selectTournament)

	const choosePlayerInParticipantsList = useCallback((n, index) => {
		if (!isFormTab) return

		const nodeIsDisable = nodeIsPlaying(n, stageState)

		if (nodeIsDisable) {
			dispatch(setShowForbiddenMessage(true))
			return
		}

		const participantIsChosen = Object.keys(chosenPlayerInList).length !== 0
		if (!participantIsChosen) {
			dispatch(setChosenPlayerInList({ player: n, index }))
		} else if (participantIsChosen && chosenPlayerInList.index !== index) {
			dispatch(setChosenPlayerInList({ player: n, index }))
		} else {
			dispatch(setChosenPlayerInList({}))
		}
	}, [dispatch, chosenPlayerInList, isFormTab, stageState])

	function listParticipantStyle(item, index) {
		let style = {}

		if (!item?.placed && isFormTab) {
			style = {
				...style,
				color: 'var(--palette-live-blue)'
			}
		}

		if (index === chosenPlayerInList.index && isFormTab) {
			style = {
				...style,
				backgroundColor: 'var(--palette-live-blue-3)',
			}
		}

		return style
	}

	console.log(playersList)
	return (
		<>
			{
				playersList?.map((item, index) =>
					<Fragment key={index}>
						{
							type === TYPE_SINGLES &&
								<Fragment key={index}>
									{
										item?.playerUid ?
											<div
												className={`participants__container single ${nodeIsPlaying(item, stageState) && isFormTab ? 'disable' : ''}`}
												key={index}
												style={listParticipantStyle(item, index)}
												onClick={() => choosePlayerInParticipantsList(item, index)}
											>
												<p className="participants-index">
													{ index + 1 }
												</p>

												<p className="participants-name single">
													{ item?.participant?.lastName } { item?.participant?.firstName }
												</p>

												<p className="participants-rating">
													[{ item?.rating }]
												</p>
											</div>
											:
											<div
												className="participants__container single"
												key={index}
												style={listParticipantStyle(item, index)}
												onClick={() => choosePlayerInParticipantsList(item, index)}
											>
												<p className="participants-index">
													{ index + 1 }
												</p>

												<p className="participants-name">
													{ item?.name || '---' }
												</p>
											</div>
									}
								</Fragment>
						}

						{
							type === TYPE_DOUBLES &&
								<Fragment key={index}>
									{
										item?.doubleUid ?
											<div
												className={`participants__container ${nodeIsPlaying(item, stageState) && isFormTab ? 'disable' : ''}`}
												key={index}
												style={listParticipantStyle(item, index)}
												onClick={() => choosePlayerInParticipantsList(item, index)}
											>
												<p className="participants-index">
													{ index + 1 }
												</p>

												<div className="participants-doubles">
													<p className="participants-name">
														{ item?.participant.lastName1 } { item?.participant.firstName1 }
													</p>

													<p className="participants-name">
														{ item?.participant.lastName2 } { item?.participant.firstName2 }
													</p>
												</div>

												<p className="participants-rating">
													[{ item?.name }]
												</p>
											</div>
											:
											<div
												className="participants__container single"
												key={index}
												style={listParticipantStyle(item, index)}
												onClick={() => choosePlayerInParticipantsList(item, index)}
											>
												<p className="participants-index">
													{ index + 1 }
												</p>

												<p className="participants-name">
													{ item?.name || '---' }
												</p>
											</div>
									}
								</Fragment>
						}
					</Fragment>
				)
			}
		</>
	)
}

export default StageParticipantsList